select oe1_0.id,r1_0.name,(select count(*) from customers ce1_0 where ce1_0.id<=? and ce1_0.name=r1_0.name),case when exists(select 1 from customers ce2_0 where ce2_0.id<=? and ce2_0.name=r1_0.name) then true else false end from orders oe1_0 left join customers r1_0 on r1_0.id=oe1_0.referrer_id and r1_0.vip where oe1_0.id<=? order by 1
